import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_layernorm(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, double eps);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
using namespace cute;
__global__ void cute_layernorm_reduce_kernel(
    const float* __restrict__ x,
    double* __restrict__ sum_buf,
    double* __restrict__ sqsum_buf,
    int batch, int N, int blocksPerRow)
{
    int b = blockIdx.x;
    int chunk = blockIdx.y;
    if (b >= batch) return;
    const float* xRow = x + (size_t)b * N;
    int N4 = N / 4;
    int rem_start = N4 * 4;
    int chunkSize4 = (N4 + blocksPerRow - 1) / blocksPerRow;
    int start4 = chunk * chunkSize4;
    int end4 = start4 + chunkSize4;
    if (end4 > N4) end4 = N4;
    const float4* xRow4 = reinterpret_cast<const float4*>(xRow);
    int tid = threadIdx.x;
    int nthreads = blockDim.x;
    int lane = tid & 31;
    int warpId = tid >> 5;
    int numWarps = (nthreads + 31) >> 5;
    extern __shared__ double sdata[];
    double* s_sum = sdata;
    double* s_sqsum = sdata + numWarps;
    double local_sum = 0.0;
    double local_sqsum = 0.0;
    for (int i = start4 + tid; i < end4; i += nthreads) {
        float4 v = xRow4[i];
        local_sum += (double)v.x + (double)v.y + (double)v.z + (double)v.w;
        local_sqsum += (double)v.x * v.x + (double)v.y * v.y + (double)v.z * v.z + (double)v.w * v.w;
    }
    if (chunk == 0) {
        for (int i = rem_start + tid; i < N; i += nthreads) {
            float v = xRow[i];
            local_sum += (double)v;
            local_sqsum += (double)v * v;
        }
    }
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
        local_sum += __shfl_down_sync(0xffffffff, local_sum, offset);
        local_sqsum += __shfl_down_sync(0xffffffff, local_sqsum, offset);
    }
    if (lane == 0) {
        s_sum[warpId] = local_sum;
        s_sqsum[warpId] = local_sqsum;
    }
    __syncthreads();
    if (tid == 0) {
        double block_sum = 0.0;
        double block_sqsum = 0.0;
        for (int w = 0; w < numWarps; ++w) {
            block_sum += s_sum[w];
            block_sqsum += s_sqsum[w];
        }
        atomicAdd(&sum_buf[b], block_sum);
        atomicAdd(&sqsum_buf[b], block_sqsum);
    }
}
__global__ void cute_layernorm_finalize_kernel(
    const double* __restrict__ sum_buf,
    const double* __restrict__ sqsum_buf,
    float* __restrict__ mean_buf,
    float* __restrict__ invstd_buf,
    int batch, int N, float eps)
{
    int b = blockIdx.x * blockDim.x + threadIdx.x;
    if (b >= batch) return;
    double total_sum = sum_buf[b];
    double total_sqsum = sqsum_buf[b];
    double mean_val = total_sum / (double)N;
    double meansq_val = total_sqsum / (double)N;
    double var = meansq_val - mean_val * mean_val;
    if (var < 0.0) var = 0.0;
    mean_buf[b] = (float)mean_val;
    invstd_buf[b] = (float)(1.0 / sqrt(var + (double)eps));
}
__global__ void cute_layernorm_normalize_kernel(
    const float* __restrict__ x,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ y,
    const float* __restrict__ mean_buf,
    const float* __restrict__ invstd_buf,
    int batch, int N, int blocksPerRow)
{
    int b = blockIdx.x;
    int chunk = blockIdx.y;
    if (b >= batch) return;
    const float* xRow = x + (size_t)b * N;
    float* yRow = y + (size_t)b * N;
    int N4 = N / 4;
    int rem_start = N4 * 4;
    int chunkSize4 = (N4 + blocksPerRow - 1) / blocksPerRow;
    int start4 = chunk * chunkSize4;
    int end4 = start4 + chunkSize4;
    if (end4 > N4) end4 = N4;
    const float4* xRow4 = reinterpret_cast<const float4*>(xRow);
    float4* yRow4 = reinterpret_cast<float4*>(yRow);
    const float4* w4 = reinterpret_cast<const float4*>(weight);
    const float4* bA4 = reinterpret_cast<const float4*>(bias);
    int tid = threadIdx.x;
    int nthreads = blockDim.x;
    float mean = mean_buf[b];
    float invstd = invstd_buf[b];
    for (int i = start4 + tid; i < end4; i += nthreads) {
        float4 v = xRow4[i];
        float4 wv = w4[i];
        float4 bv = bA4[i];
        float4 outv;
        outv.x = (v.x - mean) * invstd * wv.x + bv.x;
        outv.y = (v.y - mean) * invstd * wv.y + bv.y;
        outv.z = (v.z - mean) * invstd * wv.z + bv.z;
        outv.w = (v.w - mean) * invstd * wv.w + bv.w;
        yRow4[i] = outv;
    }
    if (chunk == 0) {
        for (int i = rem_start + tid; i < N; i += nthreads) {
            float v = xRow[i];
            float norm = (v - mean) * invstd;
            yRow[i] = norm * weight[i] + bias[i];
        }
    }
}
torch::Tensor cute_layernorm(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, double eps) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda() && bias.is_cuda(), "weight/bias must be CUDA tensors");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "expect float32 tensor");
    auto x_c = x.contiguous();
    auto w_c = weight.contiguous();
    auto b_c = bias.contiguous();
    int64_t N = w_c.numel();
    int64_t total = x_c.numel();
    TORCH_CHECK(total % N == 0, "input size must be divisible by normalized_shape numel");
    int batch = (int)(total / N);
    auto y = torch::empty_like(x_c);
    int threads = 512;
    int N4 = (int)(N / 4);
    int blocksPerRow = 32;
    if (blocksPerRow > N4) blocksPerRow = (N4 > 0) ? N4 : 1;
    if (blocksPerRow < 1) blocksPerRow = 1;
    auto options_double = x_c.options().dtype(torch::kFloat64);
    auto sum_buf = torch::zeros({batch}, options_double);
    auto sqsum_buf = torch::zeros({batch}, options_double);
    auto mean_buf = torch::empty({batch}, x_c.options());
    auto invstd_buf = torch::empty({batch}, x_c.options());
    dim3 grid_rn(batch, blocksPerRow);
    dim3 block_rn(threads);
    int numWarps = (threads + 31) / 32;
    size_t shmem = 2 * (size_t)numWarps * sizeof(double);
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    cute_layernorm_reduce_kernel<<<grid_rn, block_rn, shmem, stream>>>(
        x_c.data_ptr<float>(),
        sum_buf.data_ptr<double>(),
        sqsum_buf.data_ptr<double>(),
        batch, (int)N, blocksPerRow);
    int finalize_threads = 32;
    int finalize_blocks = (batch + finalize_threads - 1) / finalize_threads;
    cute_layernorm_finalize_kernel<<<finalize_blocks, finalize_threads, 0, stream>>>(
        sum_buf.data_ptr<double>(),
        sqsum_buf.data_ptr<double>(),
        mean_buf.data_ptr<float>(),
        invstd_buf.data_ptr<float>(),
        batch, (int)N, (float)eps);
    cute_layernorm_normalize_kernel<<<grid_rn, block_rn, 0, stream>>>(
        x_c.data_ptr<float>(),
        w_c.data_ptr<float>(),
        b_c.data_ptr<float>(),
        y.data_ptr<float>(),
        mean_buf.data_ptr<float>(),
        invstd_buf.data_ptr<float>(),
        batch, (int)N, blocksPerRow);
    TORCH_CHECK(cudaGetLastError() == cudaSuccess, "CUTE layernorm launch failed");
    return y;
}
"""
cute_ext = load_inline(
    name="cute_layernorm_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_layernorm"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/workspace/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Model that performs Layer Normalization using a custom CuTe/CUDA kernel.
    """
    def __init__(self, normalized_shape: tuple) -> None:
        super(ModelNew, self).__init__()
        self.normalized_shape = normalized_shape
        self.weight = nn.Parameter(torch.ones(normalized_shape))
        self.bias = nn.Parameter(torch.zeros(normalized_shape))
        self.eps = 1e-5
        self._ext = cute_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x_cuda = x.cuda() if not x.is_cuda else x
        weight = self.weight.to(device=x_cuda.device, dtype=x_cuda.dtype)
        bias = self.bias.to(device=x_cuda.device, dtype=x_cuda.dtype)
        return self._ext.cute_layernorm(x_cuda, weight, bias, self.eps)

